    offs_v = tl.arange(0, V_HEAD_DIM_ROUNDED)
    v = load_checked_2d_65dbdfce(V, offs_n_load, offs_v, stride_vn, stride_vk, IS_DIVISIBLE, SAFE_HEAD_DIM, KV_LEN, V_HEAD_DIM)
