    stride_kz, stride_kh, stride_kn, stride_kd = 16384, 8192, 64, 1
    stride_vz, stride_vh, stride_vn, stride_vd = 16384, 8192, 64, 1
    stride_doz, stride_doh, stride_dom, stride_dod = 16384, 8192, 64, 1

    stride_dqz, stride_dqh, stride_dqm, stride_dqd = 16384, 8192, 64, 1
    stride_dvz, stride_dvh, stride_dvm, stride_dvd = 16384, 8192, 64, 1

